<div class="editor-layout"><section class="editor-canvas"><div class="editor-field"><label>Название</label><input name="title" required value="{{old('title',$record?->title)}}"></div><div class="editor-field"><label>Описание</label><textarea name="description" rows="4">{{$record?->description}}</textarea></div><div class="editor-field"><label>Поля формы</label><p>Добавляйте поля, меняйте их порядок и обязательность без редактирования кода.</p><div id="form-fields-visual"></div><button type="button" id="form-add-field" class="admin-primary">+ Добавить поле</button><details class="cms-json-fallback"><summary>Дополнительно: JSON (для сложных настроек)</summary><textarea id="form-fields-json" name="fields_json" rows="12" required>{{old('fields_json',json_encode($record?->fields??[['name'=>'name','label'=>'Имя','type'=>'text','required'=>true],['name'=>'email','label'=>'E-mail','type'=>'email','required'=>true],['name'=>'message','label'=>'Сообщение','type'=>'textarea','required'=>true]],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))}}</textarea><small>Типы: text, email, tel, textarea, select. Для select добавьте "options": ["Вариант 1","Вариант 2"].</small></details></div></section><aside class="editor-settings"><label>Slug<input name="slug" value="{{$record?->slug}}"></label><label><input type="checkbox" name="is_active" value="1" @checked($record?->is_active??true)> Форма активна</label>@if($record)<a href="{{route('forms.show',$record->slug)}}" target="_blank">Открыть публичную форму →</a>@endif</aside></div></form>
<script>
(()=>{const raw=document.getElementById("form-fields-json"),box=document.getElementById("form-fields-visual"),add=document.getElementById("form-add-field");if(!raw||!box)return;let fields;try{fields=JSON.parse(raw.value);if(!Array.isArray(fields))throw Error()}catch(e){box.textContent="Ошибка JSON. Исправьте данные в дополнительном редакторе.";return}const types=["text","email","tel","textarea","select"];const esc=s=>String(s??"").replace(/[&<>"\x27]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","\x27":"&#39;"}[c]));function sync(){raw.value=JSON.stringify(fields,null,2)}function render(){box.innerHTML="";fields.forEach((field,i)=>{const item=document.createElement("div");item.className="cms-form-field-card";item.innerHTML=`<div class="cms-form-field-head"><strong>Поле ${i+1}</strong><div><button type="button" data-action="up">↑</button><button type="button" data-action="down">↓</button><button type="button" data-action="remove">Удалить</button></div></div><label>Подпись<input data-key="label" value="${esc(field.label)}"></label><label>Имя поля (латиницей)<input data-key="name" value="${esc(field.name)}"></label><label>Тип<select data-key="type">${types.map(t=>`<option value="${t}" ${field.type===t?"selected":""}>${({text:"Текст",email:"E-mail",tel:"Телефон",textarea:"Большой текст",select:"Выбор"})[t]}</option>`).join("")}</select></label><label class="cms-form-required"><input type="checkbox" data-key="required" ${field.required?"checked":""}> Обязательное</label><label class="cms-form-options" ${field.type==="select"?"":"hidden"}>Варианты (каждый с новой строки)<textarea data-key="options" rows="3">${esc((field.options||[]).join("\n"))}</textarea></label>`;item.querySelectorAll("[data-key]").forEach(el=>el.addEventListener("input",()=>{const k=el.dataset.key;field[k]=k==="required"?el.checked:k==="options"?el.value.split("\n").map(x=>x.trim()).filter(Boolean):el.value;if(k==="type")render();sync()}));item.querySelectorAll("[data-action]").forEach(btn=>btn.addEventListener("click",()=>{const a=btn.dataset.action;if(a==="remove")fields.splice(i,1);if(a==="up"&&i>0)[fields[i-1],fields[i]]=[fields[i],fields[i-1]];if(a==="down"&&i<fields.length-1)[fields[i+1],fields[i]]=[fields[i],fields[i+1]];sync();render()}));box.append(item)});sync()}add.addEventListener("click",()=>{fields.push({name:"field_"+(Date.now()%1000000),label:"Новое поле",type:"text",required:false});render()});raw.addEventListener("input",()=>{try{const next=JSON.parse(raw.value);if(Array.isArray(next)){fields=next;render()}}catch(e){}});render()})();
</script>
